# DNSSEC NSEC3 Closest-Encloser / Opt-Out Validation — Root-Cause Fix

**Problem class:** `js-dnssec-nsec3-closest-encloser-optout-validation`
**Environment:** Node.js 20, zero external dependencies
**Deliverables:** `/workspace/dnssec-nsec3.js`, `/workspace/test-validator.js`, `/workspace/SOLUTION.md`

## 1. Root-cause analysis

A naive NSEC3 negative-answer validator accepts forgeries through four holes:

1. **Trusting hash parameters from the presented NSEC3 RR instead of the authenticated `NSEC3PARAM`.** `Iterations`/`Salt`/`Hash Algorithm` appear in every NSEC3 RDATA. If the validator hashes with `record.iterations`, an attacker can shift iterations until the forged owner names line up (*hash-iteration malleability*). Fix: hash only with the trusted NSEC3PARAM and reject any NSEC3 whose parameters differ.
2. **Not requiring the full RFC 5155 §8.3 proof.** NXDOMAIN needs (a) closest-encloser match, (b) next-closer *covered*, and (c) wildcard denial. A "stripped" proof must not fall through to insecure accept.
3. **Ignoring opt-out semantics.** An opt-out (`Flags & 0x01`) NSEC3 covering a name proves only an *insecure delegation for that name*. Using it to deny a deeper name crosses an unsigned delegation; using it to cover a DS-bearing delegation is opt-out abuse.
4. **Evaluating the proof before authenticating it.** RRSIGs must chain from a trust anchor through the DNSKEY RRset before any NSEC3 is believed.

Every rejection is a `DnssecError` with a stable `.code`, so each forgery yields a distinct named reason.

## 2. Exact fix

### 2.1 Validator (`dnssec-nsec3.js`)

```js
'use strict';
/*
 * dnssec-nsec3.js
 * Self-contained DNSSEC negative-answer validator for NSEC3 (RFC 5155).
 *
 * Implements:
 *   - RFC 5155 iterated salted SHA-1 NSEC3 hashing (base32hex, no padding)
 *   - RFC 4034 canonical RRset form + RRSIG verification (RSA/SHA-*, ECDSA, Ed25519)
 *   - DNSKEY chain of trust from configured trust anchors
 *   - closest-encloser / next-closer / wildcard-denial proofs
 *   - opt-out semantics for unsigned delegations
 *   - distinct, named rejection reasons for stripped/forged proofs
 */

const crypto = require('crypto');

/* ------------------------------------------------------------------ */
/* Errors                                                             */
/* ------------------------------------------------------------------ */

class DnssecError extends Error {
  constructor(code, message, detail) {
    super(message || code);
    this.name = 'DnssecError';
    this.code = code;
    if (detail !== undefined) this.detail = detail;
  }
}

/* ------------------------------------------------------------------ */
/* Constants                                                          */
/* ------------------------------------------------------------------ */

const TYPE = {
  A: 1, NS: 2, CNAME: 5, SOA: 6, DS: 43, RRSIG: 46,
  NSEC: 47, DNSKEY: 48, NSEC3: 50, NSEC3PARAM: 51,
};

const ALG = {
  RSASHA1: 5, RSASHA1_NSEC3: 7, RSASHA256: 8, RSASHA512: 10,
  ECDSAP256SHA256: 13, ECDSAP384SHA384: 14, ED25519: 15, ED448: 16,
};

/* ------------------------------------------------------------------ */
/* Base32hex (RFC 4648, no padding) -- order preserving               */
/* ------------------------------------------------------------------ */

const B32HEX = '0123456789ABCDEFGHIJKLMNOPQRSTUV';

function base32hexEncode(buf) {
  let bits = 0;
  let value = 0;
  let out = '';
  for (const b of buf) {
    value = (value << 8) | b;
    bits += 8;
    while (bits >= 5) {
      out += B32HEX[(value >>> (bits - 5)) & 31];
      bits -= 5;
    }
  }
  if (bits > 0) out += B32HEX[(value << (5 - bits)) & 31];
  return out;
}

function base32hexDecode(str) {
  str = String(str).toUpperCase().replace(/=+$/, '');
  let bits = 0;
  let value = 0;
  const out = [];
  for (const ch of str) {
    const idx = B32HEX.indexOf(ch);
    if (idx < 0) throw new DnssecError('BAD_BASE32HEX', `invalid base32hex character: ${ch}`);
    value = (value << 5) | idx;
    bits += 5;
    if (bits >= 8) {
      out.push((value >>> (bits - 8)) & 0xff);
      bits -= 8;
    }
  }
  return Buffer.from(out);
}

/* ------------------------------------------------------------------ */
/* DNS name helpers                                                   */
/* ------------------------------------------------------------------ */

function splitLabels(name) {
  if (name === '.' || name === '' || name == null) return [];
  return String(name).replace(/\.$/, '').split('.');
}

function lowerName(name) {
  return String(name).replace(/\.$/, '').toLowerCase();
}

function parentName(name) {
  const l = splitLabels(name);
  if (l.length <= 1) return '.';
  return l.slice(1).join('.');
}

function isSubdomainOrEqual(child, parent) {
  const c = splitLabels(child).map((s) => s.toLowerCase());
  const p = splitLabels(parent).map((s) => s.toLowerCase());
  if (p.length > c.length) return false;
  for (let i = 0; i < p.length; i++) {
    if (c[c.length - 1 - i] !== p[p.length - 1 - i]) return false;
  }
  return true;
}

/** canonical (lower-cased) uncompressed wire encoding */
function canonicalWireName(name) {
  const labels = splitLabels(name).map((s) => s.toLowerCase());
  const parts = [];
  for (const lab of labels) {
    const b = Buffer.from(lab, 'binary');
    parts.push(Buffer.from([b.length]), b);
  }
  parts.push(Buffer.from([0]));
  return Buffer.concat(parts);
}

/** ancestor chain from qname up to (and including) zone */
function ancestorChain(qname, zone) {
  const q = splitLabels(qname);
  const z = splitLabels(zone);
  const chain = [];
  for (let i = 0; i <= q.length - z.length; i++) {
    chain.push(q.slice(i).join('.'));
  }
  return chain;
}

/** immediate descendant of ceName on the path to qname */
function nextCloserName(qname, ceName) {
  const q = splitLabels(qname);
  const ce = splitLabels(ceName);
  return q.slice(q.length - ce.length - 1).join('.');
}

/* ------------------------------------------------------------------ */
/* NSEC3 hashing (RFC 5155 section 5)                                 */
/* ------------------------------------------------------------------ */

function nsec3Hash(name, salt, iterations, hashAlg = 1) {
  if (hashAlg !== 1) {
    throw new DnssecError('NSEC3_UNSUPPORTED_HASH_ALG', `unsupported NSEC3 hash algorithm ${hashAlg}`);
  }
  const x = canonicalWireName(name);
  const s = Buffer.isBuffer(salt) ? salt : Buffer.from(salt || '', 'hex');
  let ih = crypto.createHash('sha1').update(Buffer.concat([x, s])).digest();
  for (let i = 0; i < iterations; i++) {
    ih = crypto.createHash('sha1').update(Buffer.concat([ih, s])).digest();
  }
  return ih;
}

function nsec3HashB32(name, salt, iterations, hashAlg = 1) {
  return base32hexEncode(nsec3Hash(name, salt, iterations, hashAlg));
}

/* ------------------------------------------------------------------ */
/* Type bitmaps (RFC 4034 section 4.1.2)                              */
/* ------------------------------------------------------------------ */

function parseTypeBitmap(buf) {
  const types = new Set();
  let i = 0;
  while (i < buf.length) {
    if (i + 2 > buf.length) throw new DnssecError('BAD_TYPE_BITMAP', 'truncated type bitmap');
    const window = buf[i++];
    const len = buf[i++];
    if (i + len > buf.length) throw new DnssecError('BAD_TYPE_BITMAP', 'truncated type bitmap window');
    for (let j = 0; j < len; j++) {
      const octet = buf[i + j];
      for (let bit = 0; bit < 8; bit++) {
        if (octet & (0x80 >> bit)) types.add(window * 256 + j * 8 + bit);
      }
    }
    i += len;
  }
  return types;
}

function encodeTypeBitmap(types) {
  const sorted = [...types].sort((a, b) => a - b);
  const windows = new Map();
  for (const t of sorted) {
    const w = Math.floor(t / 256);
    if (!windows.has(w)) windows.set(w, new Set());
    windows.get(w).add(t % 256);
  }
  const parts = [];
  for (const w of [...windows.keys()].sort((a, b) => a - b)) {
    const bitset = windows.get(w);
    const maxByte = Math.max(...bitset) >> 3;
    const bytes = Buffer.alloc(maxByte + 1);
    for (const bit of bitset) bytes[bit >> 3] |= 0x80 >> (bit & 7);
    parts.push(Buffer.from([w, bytes.length]), bytes);
  }
  return Buffer.concat(parts);
}

/* ------------------------------------------------------------------ */
/* RR / RRSIG parsing and verification                                */
/* ------------------------------------------------------------------ */

function parseWireName(buf, offset) {
  const labels = [];
  let o = offset;
  for (;;) {
    if (o >= buf.length) throw new DnssecError('BAD_NAME', 'truncated name');
    const len = buf[o++];
    if (len === 0) break;
    if (len & 0xc0) throw new DnssecError('BAD_NAME', 'compression not allowed here');
    if (o + len > buf.length) throw new DnssecError('BAD_NAME', 'truncated label');
    labels.push(buf.subarray(o, o + len).toString('binary'));
    o += len;
  }
  const wire = Buffer.from(buf.subarray(offset, o));
  const name = labels.join('.') || '.';
  return { name, wire, length: o - offset };
}

function parseRrsig(buf) {
  if (buf.length < 18) throw new DnssecError('BAD_RRSIG', 'RRSIG too short');
  let o = 0;
  const typeCovered = buf.readUInt16BE(o); o += 2;
  const algorithm = buf[o++];
  const labels = buf[o++];
  const originalTtl = buf.readUInt32BE(o); o += 4;
  const expiration = buf.readUInt32BE(o); o += 4;
  const inception = buf.readUInt32BE(o); o += 4;
  const keyTag = buf.readUInt16BE(o); o += 2;
  const parsed = parseWireName(buf, o);
  o += parsed.length;
  const signature = buf.subarray(o);
  return {
    typeCovered, algorithm, labels, originalTtl, expiration, inception,
    keyTag, signer: parsed.name, signerWire: parsed.wire, signature,
  };
}

function rrsigPrefix(fields) {
  const signerWire = fields.signerWire || canonicalWireName(fields.signer);
  const out = Buffer.alloc(18 + signerWire.length);
  out.writeUInt16BE(fields.typeCovered, 0);
  out[2] = fields.algorithm;
  out[3] = fields.labels;
  out.writeUInt32BE(fields.originalTtl, 4);
  out.writeUInt32BE(fields.expiration, 8);
  out.writeUInt32BE(fields.inception, 12);
  out.writeUInt16BE(fields.keyTag, 16);
  signerWire.copy(out, 18);
  return out;
}

function canonicalRrset(rrset, ttl) {
  const owner = canonicalWireName(rrset.name);
  const rdatas = [...rrset.rdatas].sort(Buffer.compare);
  const parts = [];
  for (const rd of rdatas) {
    const h = Buffer.alloc(owner.length + 10);
    owner.copy(h, 0);
    h.writeUInt16BE(rrset.type, owner.length);
    h.writeUInt16BE(rrset.class, owner.length + 2);
    h.writeUInt32BE(ttl, owner.length + 4);
    h.writeUInt16BE(rd.length, owner.length + 8);
    parts.push(h, rd);
  }
  return Buffer.concat(parts);
}

function rrsigSignedData(rrsig, rrset) {
  return Buffer.concat([rrsigPrefix(rrsig), canonicalRrset(rrset, rrsig.originalTtl)]);
}

/* ------------------------------------------------------------------ */
/* DNSKEY handling                                                    */
/* ------------------------------------------------------------------ */

function parseDnskey(buf) {
  if (buf.length < 4) throw new DnssecError('BAD_DNSKEY', 'DNSKEY too short');
  const flags = buf.readUInt16BE(0);
  const protocol = buf[2];
  const algorithm = buf[3];
  const publicKey = buf.subarray(4);
  return { flags, protocol, algorithm, publicKey, rdata: Buffer.from(buf) };
}

/** RFC 4034 Appendix B key tag */
function dnskeyTag(rdata) {
  let ac = 0;
  for (let i = 0; i < rdata.length; i++) {
    ac += (i & 1) ? rdata[i] : (rdata[i] << 8);
  }
  ac += (ac >> 16) & 0xffff;
  return ac & 0xffff;
}

function b64u(buf) {
  return Buffer.from(buf).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}
function b64uDecode(s) {
  return Buffer.from(String(s).replace(/-/g, '+').replace(/_/g, '/'), 'base64');
}

/** Convert a DNSKEY to a Node key object + hash algorithm. */
function dnskeyToNodeKey(dnskey) {
  const pub = dnskey.publicKey;
  switch (dnskey.algorithm) {
    case ALG.RSASHA1:
    case ALG.RSASHA1_NSEC3:
    case ALG.RSASHA256:
    case ALG.RSASHA512: {
      let o = 0;
      let elen = pub[o++];
      if (elen === 0) { elen = pub.readUInt16BE(o); o += 2; }
      const e = pub.subarray(o, o + elen); o += elen;
      const n = pub.subarray(o);
      // strip leading zeros for JWK
      let nn = n;
      while (nn.length > 1 && nn[0] === 0) nn = nn.subarray(1);
      const key = crypto.createPublicKey({
        key: { kty: 'RSA', n: b64u(nn), e: b64u(e) },
        format: 'jwk',
      });
      const hash = dnskey.algorithm === ALG.RSASHA512 ? 'sha512'
        : dnskey.algorithm === ALG.RSASHA256 ? 'sha256' : 'sha1';
      return { key, hash, opts: undefined };
    }
    case ALG.ECDSAP256SHA256:
    case ALG.ECDSAP384SHA384: {
      if (pub[0] !== 0x04) throw new DnssecError('BAD_DNSKEY', 'only uncompressed EC points supported');
      const half = (pub.length - 1) / 2;
      const x = pub.subarray(1, 1 + half);
      const y = pub.subarray(1 + half);
      const crv = dnskey.algorithm === ALG.ECDSAP256SHA256 ? 'P-256' : 'P-384';
      const key = crypto.createPublicKey({
        key: { kty: 'EC', crv, x: b64u(x), y: b64u(y) },
        format: 'jwk',
      });
      const hash = dnskey.algorithm === ALG.ECDSAP256SHA256 ? 'sha256' : 'sha384';
      return { key, hash, opts: { key, dsaEncoding: 'ieee-p1363' } };
    }
    case ALG.ED25519:
    case ALG.ED448: {
      const crv = dnskey.algorithm === ALG.ED25519 ? 'Ed25519' : 'Ed448';
      const key = crypto.createPublicKey({
        key: { kty: 'OKP', crv, x: b64u(pub) },
        format: 'jwk',
      });
      return { key, hash: null, opts: undefined };
    }
    default:
      throw new DnssecError('UNSUPPORTED_DNSKEY_ALG', `unsupported DNSKEY algorithm ${dnskey.algorithm}`);
  }
}

function verifySignature(algorithm, data, nodeKey, signature) {
  try {
    if (algorithm === ALG.ED25519 || algorithm === ALG.ED448) {
      return crypto.verify(null, data, nodeKey.opts ? nodeKey.opts.key : nodeKey.key, signature);
    }
    const keyArg = nodeKey.opts || nodeKey.key;
    return crypto.verify(nodeKey.hash, data, keyArg, signature);
  } catch (e) {
    return false;
  }
}

function verifyRrsig(rrset, rrsig, nodeKey) {
  const data = rrsigSignedData(rrsig, rrset);
  return verifySignature(rrsig.algorithm, data, nodeKey, rrsig.signature);
}

/* ------------------------------------------------------------------ */
/* NSEC3 RDATA                                                        */
/* ------------------------------------------------------------------ */

function parseNsec3Rdata(buf) {
  if (buf.length < 5) throw new DnssecError('BAD_NSEC3', 'NSEC3 RDATA too short');
  let o = 0;
  const hashAlg = buf[o++];
  const flags = buf[o++];
  const iterations = buf.readUInt16BE(o); o += 2;
  const saltLen = buf[o++];
  if (o + saltLen > buf.length) throw new DnssecError('BAD_NSEC3', 'truncated salt');
  const salt = Buffer.from(buf.subarray(o, o + saltLen)); o += saltLen;
  const hashLen = buf[o++];
  if (o + hashLen > buf.length) throw new DnssecError('BAD_NSEC3', 'truncated next hashed owner');
  const nextHashed = Buffer.from(buf.subarray(o, o + hashLen)); o += hashLen;
  const types = parseTypeBitmap(buf.subarray(o));
  return { hashAlg, flags, iterations, salt, nextHashed, types };
}

function encodeNsec3Rdata({ hashAlg = 1, flags = 0, iterations, salt, nextHashed, types }) {
  const s = Buffer.isBuffer(salt) ? salt : Buffer.from(salt || '', 'hex');
  const typesBuf = encodeTypeBitmap(types || []);
  const head = Buffer.alloc(5 + s.length + 1);
  head[0] = hashAlg;
  head[1] = flags;
  head.writeUInt16BE(iterations, 2);
  head[4] = s.length;
  s.copy(head, 5);
  head[5 + s.length] = nextHashed.length;
  return Buffer.concat([head, nextHashed, typesBuf]);
}

function nsec3RdataToRecord(rrset) {
  const parsed = parseNsec3Rdata(rrset.rdatas[0]);
  const firstLabel = splitLabels(rrset.name)[0];
  return {
    ...parsed,
    owner: rrset.name,
    ownerHash: base32hexDecode(firstLabel),
    rrset,
  };
}

/* ------------------------------------------------------------------ */
/* NSEC3 "covers"                                                     */
/* ------------------------------------------------------------------ */

function hashCovers(record, hash) {
  const o = record.ownerHash;
  const n = record.nextHashed;
  const cmpON = Buffer.compare(o, n);
  if (cmpON < 0) {
    return Buffer.compare(o, hash) < 0 && Buffer.compare(hash, n) < 0;
  }
  // owner >= next: interval wraps (owner == next covers all but owner)
  return Buffer.compare(o, hash) < 0 || Buffer.compare(hash, n) < 0;
}

/* ------------------------------------------------------------------ */
/* DNSKEY chain of trust                                              */
/* ------------------------------------------------------------------ */

function validateDnskeyChain(dnskeyRrset, trustAnchors, zone, now) {
  if (!trustAnchors || trustAnchors.length === 0) {
    throw new DnssecError('NO_TRUST_ANCHOR', 'no trust anchors configured');
  }
  if (!dnskeyRrset || !dnskeyRrset.rrsig) {
    throw new DnssecError('DNSKEY_RRSIG_MISSING', 'DNSKEY RRset has no RRSIG');
  }
  const rrsig = dnskeyRrset.rrsig;
  if (lowerName(rrsig.signer) !== lowerName(zone)) {
    throw new DnssecError('DNSKEY_SIGNER_MISMATCH', `DNSKEY RRSIG signer ${rrsig.signer} != zone ${zone}`);
  }
  if (now != null) {
    if (now < rrsig.inception) throw new DnssecError('DNSKEY_SIG_NOT_YET_VALID', 'DNSKEY RRSIG not yet valid');
    if (now > rrsig.expiration) throw new DnssecError('DNSKEY_SIG_EXPIRED', 'DNSKEY RRSIG expired');
  }

  const anchor = trustAnchors.find((a) => dnskeyTag(a.rdata) === rrsig.keyTag && a.algorithm === rrsig.algorithm);
  if (!anchor) {
    throw new DnssecError('DNSKEY_KEY_TAG_MISMATCH', 'no trust anchor matches DNSKEY RRSIG key tag');
  }
  let nodeKey;
  try {
    nodeKey = dnskeyToNodeKey(anchor);
  } catch (e) {
    throw new DnssecError('DNSKEY_KEY_INVALID', `trust anchor key unusable: ${e.message}`);
  }
  const rrsetForVerify = { ...dnskeyRrset, rrsig: undefined };
  if (!verifyRrsig(rrsetForVerify, rrsig, nodeKey)) {
    throw new DnssecError('DNSKEY_RRSIG_INVALID', 'DNSKEY RRset RRSIG did not verify against trust anchor');
  }

  // The entire validated DNSKEY RRset is now trusted.
  const keys = [];
  for (const rd of dnskeyRrset.rdatas) {
    const dk = parseDnskey(rd);
    keys.push({ tag: dnskeyTag(rd), algorithm: dk.algorithm, dnskey: dk });
  }
  return keys;
}

/* ------------------------------------------------------------------ */
/* NSEC3 RRset signature validation                                   */
/* ------------------------------------------------------------------ */

function validateNsec3Signatures(nsec3Rrsets, dnskeyRrset, trustAnchors, zone, now) {
  const trustedKeys = validateDnskeyChain(dnskeyRrset, trustAnchors, zone, now);
  const out = [];
  for (const rr of nsec3Rrsets) {
    if (!rr.rrsig) {
      throw new DnssecError('NSEC3_SIG_MISSING', `NSEC3 RRset ${rr.name} has no RRSIG`);
    }
    const rrsig = rr.rrsig;
    if (lowerName(rrsig.signer) !== lowerName(zone)) {
      throw new DnssecError('NSEC3_SIGNER_MISMATCH', `NSEC3 RRSIG signer ${rrsig.signer} != zone ${zone}`);
    }
    if (now != null) {
      if (now < rrsig.inception) throw new DnssecError('NSEC3_SIG_NOT_YET_VALID', `NSEC3 RRSIG at ${rr.name} not yet valid`);
      if (now > rrsig.expiration) throw new DnssecError('NSEC3_SIG_EXPIRED', `NSEC3 RRSIG at ${rr.name} expired`);
    }
    const key = trustedKeys.find((k) => k.tag === rrsig.keyTag && k.algorithm === rrsig.algorithm);
    if (!key) {
      throw new DnssecError('NSEC3_KEY_NOT_FOUND', `no trusted DNSKEY matches NSEC3 RRSIG key tag ${rrsig.keyTag}`);
    }
    let nodeKey;
    try {
      nodeKey = dnskeyToNodeKey(key.dnskey);
    } catch (e) {
      throw new DnssecError('NSEC3_KEY_INVALID', `NSEC3 signing key unusable: ${e.message}`);
    }
    const rrset = { ...rr, rrsig: undefined };
    if (!verifyRrsig(rrset, rrsig, nodeKey)) {
      throw new DnssecError('NSEC3_RRSIG_INVALID', `NSEC3 RRSIG at ${rr.name} did not verify`);
    }
    out.push(nsec3RdataToRecord(rr));
  }
  return out;
}

/* ------------------------------------------------------------------ */
/* Negative-answer proof machinery                                    */
/* ------------------------------------------------------------------ */

function findClosestEncloser(qname, zone, records, params) {
  for (const name of ancestorChain(qname, zone)) {
    const h = nsec3Hash(name, params.salt, params.iterations, params.hashAlg);
    const rec = records.find((r) => r.ownerHash.equals(h));
    if (rec) return { name, record: rec };
  }
  return null;
}

function validateNegativeAnswer(zoneData, query, options = {}) {
  const {
    zone, dnskeyRrset, nsec3param, trustAnchors,
    signedDelegations = new Set(),
  } = zoneData;
  const { qname, qtype } = query;
  const now = options.now === undefined ? Math.floor(Date.now() / 1000) : options.now;
  const allowInsecureOptout = options.allowInsecureOptout !== false;

  if (!isSubdomainOrEqual(qname, zone)) {
    throw new DnssecError('OUT_OF_ZONE', `${qname} is not inside ${zone}`);
  }
  if (!nsec3param) {
    throw new DnssecError('NSEC3PARAM_MISSING', 'trusted NSEC3PARAM not supplied');
  }

  // 1. Authenticate the NSEC3 RRsets up the DNSKEY chain of trust.
  const records = validateNsec3Signatures(zoneData.nsec3Rrsets || [], dnskeyRrset, trustAnchors, zone, now);

  // 2. Enforce that every presented NSEC3 uses the *trusted* zone parameters.
  //    This blocks hash-iteration / salt malleability even when an attacker
  //    manages to produce a self-consistent alternate chain.
  for (const r of records) {
    if (r.hashAlg !== nsec3param.hashAlg) {
      throw new DnssecError('NSEC3_HASH_ALG_MISMATCH',
        `NSEC3 hash algorithm ${r.hashAlg} != trusted ${nsec3param.hashAlg}`);
    }
    if (r.iterations !== nsec3param.iterations) {
      throw new DnssecError('NSEC3_ITERATION_MISMATCH',
        `NSEC3 iterations ${r.iterations} != trusted ${nsec3param.iterations} (hash-iteration malleability)`);
    }
    if (!r.salt.equals(nsec3param.salt)) {
      throw new DnssecError('NSEC3_SALT_MISMATCH', 'NSEC3 salt does not match trusted NSEC3PARAM');
    }
  }

  // 3. Closest encloser.
  const ce = findClosestEncloser(qname, zone, records, nsec3param);
  if (!ce) {
    throw new DnssecError('NSEC3_NO_CLOSEST_ENCLOSER',
      `stripped proof: no NSEC3 matches any ancestor of ${qname}`);
  }

  const ceName = lowerName(ce.name);
  const qLower = lowerName(qname);

  // --- NODATA: the name itself exists (closest encloser == qname) ---
  if (ceName === qLower) {
    const present = ce.record.types;
    if (present.has(qtype)) {
      throw new DnssecError('NSEC3_NODATA_TYPE_PRESENT',
        `bogus NODATA: NSEC3 for ${qname} asserts type ${qtype} exists`);
    }
    if (present.has(TYPE.CNAME)) {
      throw new DnssecError('NSEC3_NODATA_CNAME_PRESENT',
        `bogus NODATA: ${qname} is a CNAME`);
    }
    return { status: 'secure-nodata', closestEncloser: ce.name };
  }

  // --- NXDOMAIN / wildcard handling ---
  const nextCloser = nextCloserName(qname, ce.name);
  const nextHash = nsec3Hash(nextCloser, nsec3param.salt, nsec3param.iterations, nsec3param.hashAlg);
  const nextCover = records.find((r) => hashCovers(r, nextHash));
  if (!nextCover) {
    throw new DnssecError('NSEC3_MISSING_NEXT_CLOSER',
      `stripped proof: no NSEC3 covers next-closer name ${nextCloser}`);
  }

  const wildcardName = '*.' + ce.name;
  const wildcardHash = nsec3Hash(wildcardName, nsec3param.salt, nsec3param.iterations, nsec3param.hashAlg);
  const wildcardMatch = records.find((r) => r.ownerHash.equals(wildcardHash));
  const wildcardCover = records.find((r) => hashCovers(r, wildcardHash));

  const nextOptOut = (nextCover.flags & 0x01) === 0x01;

  if (nextOptOut) {
    // Opt-out only permits an *insecure delegation* result for the next
    // closer name itself. It may never be used to deny names below it
    // (that would cross an unsigned delegation).
    if (nextCloser !== qLower) {
      throw new DnssecError('NSEC3_OPTOUT_CROSSES_UNSIGNED_DELEGATION',
        `opt-out NSEC3 covers ${nextCloser} but is used to deny ${qname} below it`);
    }
    if (signedDelegations.has(nextCloser)) {
      throw new DnssecError('NSEC3_OPTOUT_ABUSE_SIGNED_DELEGATION',
        `opt-out NSEC3 covers signed delegation ${nextCloser}`);
    }
    if (!allowInsecureOptout) {
      throw new DnssecError('NSEC3_OPTOUT_INSECURE',
        `opt-out resolves ${qname} to an insecure delegation`);
    }
    return { status: 'insecure-delegation', closestEncloser: ce.name, nextCloser };
  }

  // Wildcard NODATA: an existing wildcard lacks the requested type.
  if (wildcardMatch) {
    if (wildcardMatch.types.has(qtype)) {
      throw new DnssecError('NSEC3_WILDCARD_TYPE_PRESENT',
        `bogus negative answer: ${wildcardName} asserts type ${qtype} exists`);
    }
    return { status: 'secure-wildcard-nodata', closestEncloser: ce.name, nextCloser };
  }

  // Wildcard denial: no wildcard may exist at the closest encloser.
  if (!wildcardCover) {
    throw new DnssecError('NSEC3_MISSING_WILDCARD_DENIAL',
      `stripped proof: no NSEC3 covers wildcard ${wildcardName}`);
  }

  return { status: 'secure-nxdomain', closestEncloser: ce.name, nextCloser };
}

/* ------------------------------------------------------------------ */
/* Convenience: classify a thrown DnssecError                         */
/* ------------------------------------------------------------------ */

function reasonCode(err) {
  return err && err.code ? err.code : 'UNKNOWN';
}

module.exports = {
  DnssecError, TYPE, ALG,
  base32hexEncode, base32hexDecode,
  splitLabels, lowerName, parentName, isSubdomainOrEqual,
  canonicalWireName, ancestorChain, nextCloserName,
