'use strict';
/*
 * test-validator.js -- verification suite for dnssec-nsec3.js
 *
 * Generates a fully signed NSEC3 zone (RSA/SHA-256 KSK + ZSK), then runs
 * positive and adversarial negative-answer validation cases.
 */

const crypto = require('crypto');
const assert = require('assert');
const V = require('./dnssec-nsec3.js');

/* ------------------------- signing helpers ------------------------- */

function b64uDecode(s) {
  return Buffer.from(String(s).replace(/-/g, '+').replace(/_/g, '/'), 'base64');
}

function rsaPubFromJwk(jwk) {
  const e = b64uDecode(jwk.e);
  let n = b64uDecode(jwk.n);
  while (n.length > 1 && n[0] === 0) n = n.subarray(1);
  const elen = e.length;
  let prefix;
  if (elen < 256) prefix = Buffer.from([elen]);
  else { prefix = Buffer.alloc(3); prefix[0] = 0; prefix.writeUInt16BE(elen, 1); }
  return Buffer.concat([prefix, e, n]);
}

function makeDnskey({ flags, algorithm = 8, jwk }) {
  const pub = rsaPubFromJwk(jwk);
  const rdata = Buffer.alloc(4 + pub.length);
  rdata.writeUInt16BE(flags, 0);
  rdata[2] = 3;
  rdata[3] = algorithm;
  pub.copy(rdata, 4);
  return { flags, protocol: 3, algorithm, publicKey: pub, rdata };
}

function signRrset(rrset, privKey, { algorithm = 8, signer, keyTag, inception, expiration }) {
  const labels = V.splitLabels(rrset.name).filter((l) => l !== '*').length;
  const head = V.rrsigPrefix({
    typeCovered: rrset.type, algorithm, labels,
    originalTtl: rrset.ttl, expiration, inception, keyTag, signer,
  });
  const data = Buffer.concat([head, V.canonicalRrset(rrset, rrset.ttl)]);
  const sig = crypto.sign('sha256', data, privKey);
  return V.parseRrsig(Buffer.concat([head, sig]));
}

/* ------------------------- zone builder ---------------------------- */

let clock = Math.floor(Date.now() / 1000);

function buildZone({
  zone = 'example', saltHex = 'aabbccdd', iterations = 12, optout = false,
  names = ['example', 'www.example', 'mail.example', 'signed.example'],
  omit = [], signedDelegations = [], typeMap = {}, iterationsOverride,
} = {}) {
  const kskPair = crypto.generateKeyPairSync('rsa', { modulusLength: 2048 });
  const zskPair = crypto.generateKeyPairSync('rsa', { modulusLength: 2048 });
  const ksk = makeDnskey({ flags: 257, jwk: kskPair.publicKey.export({ format: 'jwk' }) });
  const zsk = makeDnskey({ flags: 256, jwk: zskPair.publicKey.export({ format: 'jwk' }) });
  const inception = clock - 3600;
  const expiration = clock + 86400;
  const kskTag = V.dnskeyTag(ksk.rdata);
  const zskTag = V.dnskeyTag(zsk.rdata);

  const dnskeyRrsig = signRrset(
    { name: zone, type: V.TYPE.DNSKEY, class: 1, ttl: 3600, rdatas: [ksk.rdata, zsk.rdata] },
    kskPair.privateKey, { signer: zone, keyTag: kskTag, inception, expiration });
  const dnskeyRrset = {
    name: zone, type: V.TYPE.DNSKEY, class: 1, ttl: 3600,
    rdatas: [ksk.rdata, zsk.rdata], rrsig: dnskeyRrsig,
  };

  const salt = Buffer.from(saltHex, 'hex');
  const entries = names
    .filter((n) => !omit.includes(n))
    .map((n) => ({ name: n, hash: V.nsec3Hash(n, salt, iterations) }));
  entries.sort((a, b) => Buffer.compare(a.hash, b.hash));
  const N = entries.length;

  function typesFor(name) {
    if (typeMap[name]) return typeMap[name];
    if (name === zone) return [V.TYPE.SOA, V.TYPE.NS, V.TYPE.DNSKEY, V.TYPE.NSEC3PARAM, V.TYPE.RRSIG];
    if (name.startsWith('*.')) return [V.TYPE.A, V.TYPE.RRSIG];
    if (signedDelegations.includes(name)) return [V.TYPE.DS, V.TYPE.NS, V.TYPE.RRSIG];
    return [V.TYPE.A, V.TYPE.RRSIG];
  }

  const nsec3Rrsets = entries.map((e, i) => {
    const next = entries[(i + 1) % N].hash;
    const rdata = V.encodeNsec3Rdata({
      hashAlg: 1, flags: optout ? 1 : 0, iterations, salt, nextHashed: next, types: typesFor(e.name),
    });
    const owner = V.base32hexEncode(e.hash) + '.' + zone;
    const rrsig = signRrset(
      { name: owner, type: V.TYPE.NSEC3, class: 1, ttl: 3600, rdatas: [rdata] },
      zskPair.privateKey, { signer: zone, keyTag: zskTag, inception, expiration });
    return { name: owner, type: V.TYPE.NSEC3, class: 1, ttl: 3600, rdatas: [rdata], rrsig };
  });

  return {
    zone, dnskeyRrset, nsec3Rrsets,
    nsec3param: { hashAlg: 1, flags: optout ? 1 : 0, iterations: iterationsOverride ?? iterations, salt },
    trustAnchors: [ksk],
    signedDelegations: new Set(signedDelegations),
    zskTag, kskTag, now: clock,
  };
}

/* ------------------------- test utilities -------------------------- */

function tryValidate(zone, query) {
  try {
    return { ok: true, result: V.validateNegativeAnswer(zone, query) };
  } catch (e) {
    return { ok: false, code: V.reasonCode(e), message: e.message };
  }
}

function expectStatus(zone, query, status, label) {
  const r = tryValidate(zone, query);
  assert.ok(r.ok, `${label}: unexpectedly failed with ${r.code}: ${r.message}`);
  assert.strictEqual(r.result.status, status, `${label}: expected ${status}, got ${r.result.status}`);
  return r.result;
}

function expectCode(zone, query, code, label) {
  const r = tryValidate(zone, query);
  assert.ok(!r.ok, `${label}: expected failure ${code}, but succeeded with ${r.result && r.result.status}`);
  assert.strictEqual(r.code, code, `${label}: expected ${code}, got ${r.code} (${r.message})`);
  return r;
}

function covering(rrsets, name, salt, iterations) {
  const h = V.nsec3Hash(name, salt, iterations);
  return rrsets.find((rr) => V.hashCovers(V.nsec3RdataToRecord(rr), h));
}

