const zoneData = {
  zone: 'example',
  dnskeyRrset: { name, type: 48, class: 1, ttl, rdatas: [...], rrsig },   // authenticated
  nsec3Rrsets: [ { name, type: 50, class: 1, ttl, rdatas: [rdata], rrsig } ],
  nsec3param:  { hashAlg: 1, flags, iterations, salt },                   // trusted source
  trustAnchors: [ parsedDnskey ],                                         // secure entry point
  signedDelegations: new Set(['secure.example']),                         // names with a DS RRset
};

const result = validateNegativeAnswer(zoneData, { qname: 'nope.example', qtype: 1 });
// -> { status: 'secure-nxdomain', closestEncloser: 'example', nextCloser: 'nope.example' }
//   or { status: 'secure-nodata' | 'secure-wildcard-nodata' | 'insecure-delegation' }
//   or throws DnssecError({ code: 'NSEC3_...' })
